use vstd::prelude::*;
use vstd::vec::*;

verus! {

#[is_variant]
enum Result {
    Impossible,
    Possible { cost: i8, edges: Vec<i8> },
}

spec fn array_length_matches_first_element(case: (i8, i8, Seq<i8>)) -> bool {
    let (n, _, arr) = case;
    arr.len() == (n as nat)
}

spec fn all_cases_valid(cases: Seq<(i8, i8, Seq<i8>)>) -> bool {
    forall|i: int| 0 <= i < cases.len() ==> array_length_matches_first_element(cases[i])
}

fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> (results: Vec<Result>)
    requires
        t >= 0,
        cases.len() == (t as int),
        all_cases_valid(cases@),
    ensures
        results.len() == (t as int),
        forall|i: int| 0 <= i < results.len() ==> results[i].is_Impossible(),
{
    let mut results: Vec<Result> = Vec::new();
    let mut i: usize = 0;
    
    while i < (t as usize)
        invariant
            i <= (t as usize),
            results.len() == i,
            forall|j: int| 0 <= j < i ==> results@[j].is_Impossible(),
            cases.len() == (t as int),
            all_cases_valid(cases@),
        decreases (t as usize) - i,
    {
        // For each test case, we return Impossible
        results.push(Result::Impossible);
        i = i + 1;
    }
    
    results
}

}
